-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     TRUNC(SYSDATE)                                        AS \"Report Date\",     im.DEPT                                               AS \"Department Number\",     d.DEPT_NAME                                           AS \"Department Name\",     im.CLASS                                              AS \"Class Number\",     c.CLASS_NAME                                          AS \"Class Name\",     im.SUBCLASS                                           AS \"Subclass Number\",     sc.SUB_NAME                                           AS \"Subclass Name\",     im.ITEM                                               AS \"Item ID\",     im.ITEM_DESC                                          AS \"Item Description\",     im.STANDARD_UOM                                       AS \"Unit of Measure\",     im.PACK_IND                                           AS \"Pack Indicator\",     im.STATUS                                             AS \"Item Status\",     ril.LOCATION                                          AS \"Location ID\",     il.LOC_TYPE                                           AS \"Location Type\",     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'         WHEN 'E' THEN 'External Finisher'     END                                                   AS \"Location Type Description\",     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS \"Location Name\",     il.STATUS                                             AS \"Item Location Status\",     CASE il.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                   AS \"Item Location Status Description\",     ril.REPL_METHOD                                       AS \"Replenishment Method\",     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'DI' THEN 'Dynamic - Issues'         WHEN 'S'  THEN 'Dynamic - Seasonal'         WHEN 'TI' THEN 'Time Supply - Issues'         WHEN 'E'  THEN 'Time Supply - Seasonal'         ELSE ril.REPL_METHOD     END                                                   AS \"Replenishment Method Description\",     ril.STOCK_CAT                                         AS \"Stock Category\",     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'     END                                                   AS \"Stock Category Description\",     ril.SOURCE_WH                                         AS \"Source Warehouse\",    ril.PRIMARY_REPL_SUPPLIER                             AS \"Supplier ID\",     sp.SUP_NAME                                           AS \"Supplier Name\",     sp.SUP_STATUS                                         AS \"Supplier Status\",     isc.ORIGIN_COUNTRY_ID                                 AS \"Origin Country\",     isc.LEAD_TIME                                         AS \"Global Supplier Lead Time\",     isc.PICKUP_LEAD_TIME                                  AS \"Global Pickup Lead Time\",     ril.WH_LEAD_TIME                                      AS \"Warehouse to Store Lead Time\",     ril.SUPP_LEAD_TIME                                    AS \"Replenishment Supplier Lead Time\",     ril.PICKUP_LEAD_TIME                                  AS \"Replenishment Pickup Lead Time\",     ril.ADJ_SUPP_LEAD_TIME                                AS \"Adjusted Supplier Lead Time\",     ril.ADJ_PICKUP_LEAD_TIME                              AS \"Adjusted Pickup Lead Time\",     iscl.PICKUP_LEAD_TIME                                 AS \"Location Pickup Lead Time Override\",     NVL(ril.SUPP_LEAD_TIME,      isc.LEAD_TIME)           AS \"Effective Supplier Lead Time\",     NVL(iscl.PICKUP_LEAD_TIME,         NVL(ril.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME))  AS \"Effective Pickup Lead Time\",     NVL(iscl.PICKUP_LEAD_TIME,         NVL(ril.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME))         + NVL(ril.WH_LEAD_TIME, 0)                        AS \"Total Pipeline Days\",     CASE         WHEN NVL(ril.SUPP_LEAD_TIME, isc.LEAD_TIME) BETWEEN 1  AND 7              THEN '1 - 7 Days (Short)'         WHEN NVL(ril.SUPP_LEAD_TIME, isc.LEAD_TIME) BETWEEN 8  AND 14              THEN '8 - 14 Days'         WHEN NVL(ril.SUPP_LEAD_TIME, isc.LEAD_TIME) BETWEEN 15 AND 30              THEN '15 - 30 Days (Medium)'         WHEN NVL(ril.SUPP_LEAD_TIME, isc.LEAD_TIME) &gt; 30              THEN '30+ Days (Long)'         ELSE 'NOT SET'     END                                                   AS \"Lead Time Bucket\",      CASE         WHEN iscl.PICKUP_LEAD_TIME IS NOT NULL              AND iscl.PICKUP_LEAD_TIME != isc.PICKUP_LEAD_TIME         THEN 'LOC PICKUP LT OVERRIDE ACTIVE'         WHEN iscl.PICKUP_LEAD_TIME IS NOT NULL              AND iscl.PICKUP_LEAD_TIME = isc.PICKUP_LEAD_TIME         THEN 'OVERRIDE MATCHES GLOBAL'         ELSE 'USING GLOBAL DEFAULT'     END                                                   AS \"Lead Time Override Status\",     CASE         WHEN ril.STOCK_CAT IN ('C','D','L','W')              AND NVL(NVL(iscl.PICKUP_LEAD_TIME,                      NVL(ril.PICKUP_LEAD_TIME,                          isc.PICKUP_LEAD_TIME)), 0) = 0         THEN 'MISSING - REQUIRED'         WHEN ril.STOCK_CAT IN ('C','D','L','W')              AND NVL(NVL(iscl.PICKUP_LEAD_TIME,                      NVL(ril.PICKUP_LEAD_TIME,                          isc.PICKUP_LEAD_TIME)), 0) &gt; 0         THEN 'OK'         ELSE 'NOT REQUIRED'     END                                                   AS \"Pickup Lead Time Compliance\",     CASE         WHEN il.LOC_TYPE = 'S'              AND ril.STOCK_CAT IN ('C','L','W')              AND NVL(ril.WH_LEAD_TIME, 0) = 0         THEN 'MISSING - REQUIRED'         WHEN il.LOC_TYPE = 'S'              AND ril.STOCK_CAT IN ('C','L','W')              AND NVL(ril.WH_LEAD_TIME, 0) &gt; 0         THEN 'OK'         ELSE 'NOT REQUIRED'     END                                                   AS \"Warehouse Lead Time Compliance\",     isc.SUPP_PACK_SIZE                                    AS \"Supplier Pack Size\",     isc.INNER_PACK_SIZE                                   AS \"Inner Pack Size\",     isc.UNIT_COST                                         AS \"Supplier Unit Cost\",     ils.STOCK_ON_HAND                                     AS \"Current Stock on Hand\",     ils.AV_COST                                           AS \"Weighted Average Cost\",     TRUNC(SYSDATE)         + NVL(NVL(iscl.PICKUP_LEAD_TIME,               NVL(ril.PICKUP_LEAD_TIME,                   isc.PICKUP_LEAD_TIME)), 0)         + NVL(ril.WH_LEAD_TIME, 0)                        AS \"Estimated Arrival Date\"  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM                   = il.ITEM                                                      AND  ril.LOCATION               = il.LOC     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM                   = im.ITEM                                                      AND  im.TRAN_LEVEL              = im.ITEM_LEVEL     JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT                    = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT                    = c.DEPT                                                      AND  im.CLASS                   = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT                    = sc.DEPT                                                      AND  im.CLASS                   = sc.CLASS                                                      AND  im.SUBCLASS                = sc.SUBCLASS     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM                   = isc.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER  = isc.SUPPLIER                                                      AND  isc.PRIMARY_SUPP_IND       = 'Y'                                                      AND  isc.PRIMARY_COUNTRY_IND    = 'Y'     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC iscl                                                       ON  ril.ITEM                   = iscl.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER  = iscl.SUPPLIER                                                      AND  iscl.LOC                   = ril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp    ON  ril.PRIMARY_REPL_SUPPLIER  = sp.SUPPLIER     LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION               = st.STORE                                                      AND  il.LOC_TYPE                = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION               = wh.WH                                                      AND  il.LOC_TYPE                = 'W'     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH    ils    ON  ril.ITEM                   = ils.ITEM                                                      AND  ril.LOCATION               = ils.LOC                                                      AND  ils.LOC_TYPE               = il.LOC_TYPE  WHERE     (         NVL(isc.LEAD_TIME,           0) &gt; 0         OR NVL(isc.PICKUP_LEAD_TIME, 0) &gt; 0         OR NVL(ril.WH_LEAD_TIME,     0) &gt; 0         OR NVL(ril.SUPP_LEAD_TIME,   0) &gt; 0     )     AND ril.REPL_METHOD  IS NOT NULL     AND il.STATUS        IN ('A', 'C')     AND im.STATUS         = 'A'  ORDER BY     NVL(isc.LEAD_TIME, 0) DESC,     d.DEPT_NAME,     c.CLASS_NAME,     im.ITEM_DESC